solution.java:
class Solution {
    public long maxSubArray(int[] nums) {
        // Nonempty input; long protects sums beyond the int range.
        long ending = nums[0];
        long best = ending;
        for (int i = 1; i < nums.length; i++) {
            long x = nums[i];
            ending = Math.max(x, ending + x); // Restart or extend.
            best = Math.max(best, ending);
        }
        return best;
    }
}

solution.javascript:
function maxSubArray(nums) {
    // Nonempty input; sums must stay within the safe integer range.
    let ending = nums[0];
    let best = ending;
    for (let i = 1; i < nums.length; i++) {
        ending = Math.max(nums[i], ending + nums[i]); // Restart or extend.
        best = Math.max(best, ending);
    }
    return best;
}
